-- Lee 2026-11-04 "니가 건드려서 문제된거는 고치면되는데 … 일단 수정해": 내가 넣은 값 salary만 고침.
-- 입구 ingest_job의 기존 공고 고치기(job_id + update_fields)로만 — 규칙 트리거·공개 게이트 그대로.
select public.ingest_job($ingest${"title": "Anh ngữ Regal Edu Vân Dương tuyển 05 chuyên viên tuyển sinh – 13,5–20 triệu/tháng", "company": "Regal Edu Vân Dương", "category": "cskh_kinh_doanh", "occupation_code": "422", "occupation_evidence": "Tư vấn khóa học, chăm sóc phụ huynh & học viên", "salary": "13.500.000 – 20.000.000đ/tháng", "salary_min": 13500000, "salary_max": 20000000, "salary_period": "month", "location": "Đường Đàm Văn Lễ, khu phố Lãm Làng, Nam Sơn, Bắc Ninh", "employer_phone": "0865249861", "contact_zalo": "0865249861", "contact_name": "Chị Hoa", "age_min": 21, "age_max": 35, "num_hires": 5, "description": "[source:facebook] ANH NGỮ REGAL EDU VÂN DƯƠNG TUYỂN DỤNG \nᴋʜᴜ ᴠựᴄ: ᴠâɴ ᴅươɴɢ\n𝟶𝟻 ᴄʜᴜʏêɴ ᴠɪêɴ ᴛᴜʏểɴ sɪɴʜ\nThu nhập 13,5–20 triệu/tháng + thưởng\nTư vấn khóa học, chăm sóc phụ huynh & học viên\nĐộ tuổi 21–35, giao tiếp tốt, chủ động, cầu tiến\nKhông yêu cầu kinh nghiệm – được đào tạo\nQuyền lợi hấp dẫn:\nĐược đào tạo bài bản\nMôi trường trẻ trung, năng động\nLộ trình thăng tiến rõ ràng\nThu nhập & thưởng theo năng lực\nBHXH, nghỉ phép đầy đủ\nRegal Edu Vân Dương\nChị Hoa:  0865 249 861\nỨng tuyển ngay: Gửi CV qua Zalo hoặc inbox\nƯu tiên ứng viên gửi hồ sơ sớm – phỏng vấn ngay khi phù hợp!\n#RegalEdu #TuyenDung #ViecLam #TuyenSinh #GiaoVien #RegalEdu #TuyenDung #ViecLamGiaoDuc #ChuyenVienTuyenSinh #GiaoVienChuNhiem #VD11", "source_text": "ANH NGỮ REGAL EDU VÂN DƯƠNG TUYỂN DỤNG \nᴋʜᴜ ᴠựᴄ: ᴠâɴ ᴅươɴɢ\n𝟶𝟻 ᴄʜᴜʏêɴ ᴠɪêɴ ᴛᴜʏểɴ sɪɴʜ\nThu nhập 13,5–20 triệu/tháng + thưởng\nTư vấn khóa học, chăm sóc phụ huynh & học viên\nĐộ tuổi 21–35, giao tiếp tốt, chủ động, cầu tiến\nKhông yêu cầu kinh nghiệm – được đào tạo\nQuyền lợi hấp dẫn:\nĐược đào tạo bài bản\nMôi trường trẻ trung, năng động\nLộ trình thăng tiến rõ ràng\nThu nhập & thưởng theo năng lực\nBHXH, nghỉ phép đầy đủ\nRegal Edu Vân Dương\nChị Hoa:  0865 249 861\nỨng tuyển ngay: Gửi CV qua Zalo hoặc inbox\nƯu tiên ứng viên gửi hồ sơ sớm – phỏng vấn ngay khi phù hợp!\n#RegalEdu #TuyenDung #ViecLam #TuyenSinh #GiaoVien #RegalEdu #TuyenDung #ViecLamGiaoDuc #ChuyenVienTuyenSinh #GiaoVienChuNhiem #VD11", "source_url": "https://www.facebook.com/groups/timvieclamthembacninh/posts/1470270615238409/", "job_id": 5422, "update_fields": ["salary"], "channel": "sql_file"}$ingest$::jsonb) as job_id \gset
select step, outcome from public.job_ingest_log where raw_id = (select max(id) from public.job_ingest_raw where job_id = :job_id) order by array_position(array['preserve','dedup','occupation','location','publication'], step);
select id, occupation_code, category, salary, active, admin_hidden from public.local_jobs where id = :job_id;
